// Detect and attack player target - NO PATHFINDING
let target = bot.players['target_player'];

if (!target || !target.entity) {
    console.log('Target not found');
} else {
    const distance = target.entity.position.distanceTo(bot.entity.position);
    console.log('Target found at', Math.floor(distance), 'blocks');

    if (distance > 30) {
        console.log('Target too far away');
    } else {
        // Attack loop
        const maxCombatTime = 60000; // 60 seconds
        const startTime = Date.now();
        let hits = 0;

        while (target.entity && Date.now() - startTime < maxCombatTime && bot.health >= 14) {
            const dist = target.entity.position.distanceTo(bot.entity.position);

            if (dist <= 3.5) {
                // In melee range - attack
                await bot.lookAt(target.entity.position);
                await bot.attack(target);
                hits++;
                if (hits % 5 === 0) console.log('Hits:', hits, '| Health:', bot.health);
            } else if (dist <= 30) {
                // Out of range - move closer (no pathfinding)
                await bot.lookAt(target.entity.position);
                bot.setControlState('forward', true);
                bot.setControlState('sprint', true);
                await skills.wait(bot, 500);
                bot.setControlState('forward', false);
                bot.setControlState('sprint', false);
            } else {
                // Too far
                console.log('Target out of range');
                break;
            }

            await skills.wait(bot, 300);
        }

        console.log('Combat complete - Total hits:', hits, '| Final health:', bot.health);
        if (Date.now() - startTime >= maxCombatTime) {
            console.log('Combat timeout reached');
        }
    }
}
