```js
// Worker-vs-worker combat: Tank role
// Already positioned, NO PATHFINDING - direct forward movement only
// Target: primary_target, fallback to any enemy worker

const targetName = 'enemy_worker_1';
const MELEE_RANGE = 3.5;
const SEARCH_RANGE = 30;
const HEALTH_RETREAT = 14; // 7 hearts
const maxCombatTime = 60000;
const startTime = Date.now();

// Equip sword
let sword = bot.inventory.items().find(item => item.name === 'iron_sword');
if (sword) await bot.equip(sword, 'hand');

let hits = 0;
let target = bot.players[targetName];

if (!target?.entity) {
    console.log('Primary target not found, searching for enemies');
}

while ((Date.now() - startTime) < maxCombatTime) {
    // Health check - retreat if critical
    if (bot.health < HEALTH_RETREAT) {
        console.log('Health critical, retreating');
        break;
    }

    // Re-check primary target
    target = bot.players[targetName];

    // If primary gone, search for any enemy worker
    if (!target?.entity) {
        for (let playerName of Object.keys(bot.players)) {
            if (playerName.includes('enemy') || playerName.includes('worker')) {
                target = bot.players[playerName];
                if (target?.entity) {
                    console.log('Switched to target: ' + playerName);
                    break;
                }
            }
        }
    }

    // If we have a target, engage
    if (target?.entity) {
        const distance = target.entity.position.distanceTo(bot.entity.position);

        if (distance > SEARCH_RANGE) {
            console.log('Target out of range');
            break;
        }

        if (distance <= MELEE_RANGE) {
            // In melee range - attack
            await bot.lookAt(target.entity.position);
            await bot.attack(target);
            hits++;
        } else {
            // Move forward toward target - NO PATHFINDING
            await bot.lookAt(target.entity.position);
            bot.setControlState('forward', true);
        }
    } else {
        console.log('No target found');
        break;
    }

    await skills.wait(bot, 300);
}

bot.setControlState('forward', false);
console.log('Combat complete');
