```js
// MOB COMBAT: Tank attacking iron_golem
// Entity-based combat (not player-based)
const MELEE_RANGE = 3.5;
const SEARCH_RANGE = 30;
const HEALTH_RETREAT = 14; // 7 hearts
const MAX_COMBAT_TIME = 60000; // 60 seconds
const startTime = Date.now();

// Step 1: Equip best weapon
let weapon = bot.inventory.items().find(i => 
    i.name.includes('sword') || i.name.includes('axe')
);
if (weapon) {
    await bot.equip(weapon, 'hand');
}

let hits = 0;

// Step 2: Combat loop
while (Date.now() - startTime < MAX_COMBAT_TIME && bot.health >= HEALTH_RETREAT) {
    // Search for iron_golem (IMPORTANT: lowercase with underscore)
    let target = Object.values(bot.entities).find(e => 
        e.name === 'iron_golem' && 
        e.position.distanceTo(bot.entity.position) <= SEARCH_RANGE
    );

    if (!target) {
        console.log('No iron_golem found within ' + SEARCH_RANGE + ' blocks');
        break;
    }

    const dist = target.position.distanceTo(bot.entity.position);

    // Check if target too far
    if (dist > SEARCH_RANGE) {
        console.log('Golem too far away, retreating');
        break;
    }

    // In melee range - attack
    if (dist <= MELEE_RANGE) {
        await bot.lookAt(target.position);
        await bot.attack(target);
        hits++;
        if (hits % 5 === 0) {
            console.log('Hits: ' + hits + ' | Health: ' + bot.health);
        }
    } else {
        // Out of melee range - move closer (no pathfinding, direct movement)
        await bot.lookAt(target.position);
        bot.setControlState('forward', true);
    }

    await skills.wait(bot, 300);
}

// Stop movement
bot.setControlState('forward', false);

if (bot.health < HEALTH_RETREAT) {
    console.log('Health critical, retreating');
} else if (Date.now() - startTime >= MAX_COMBAT_TIME) {
    console.log('Combat timeout reached');
}

console.log('Combat complete. Total hits: ' + hits + ' | Final health: ' + bot.health);
